{
  "decision": "APPLY",
  "workflow_yaml": "name: Deploy

on:
  workflow_dispatch:
  push:
    branches:
      - main
    paths:
      - package.json

jobs:
  deploy:
    runs-on: ubuntu-latest
    timeout-minutes: 5

    steps:
      - uses: actions/checkout@v7
        with:
          fetch-depth: 0

      - name: Check simple-icons version
        id: simple_icons
        env:
          BEFORE_SHA: ${{ github.event.before }}
        run: |
          node <<'EOF'
          const { execFileSync } = require('node:child_process');
          const { readFileSync, appendFileSync } = require('node:fs');

          const beforeSha = process.env.BEFORE_SHA;
          const outputPath = process.env.GITHUB_OUTPUT;
          const zeroSha = /^0{40}$/;

          const getSimpleIconsVersion = (content) => {
            return JSON.parse(content).dependencies?.['simple-icons'] ?? null;
          };

          const currentVersion = getSimpleIconsVersion(readFileSync('package.json', 'utf8'));
          let previousVersion = null;

          if (beforeSha && !zeroSha.test(beforeSha)) {
            try {
              previousVersion = getSimpleIconsVersion(
                execFileSync('git', ['show', `${beforeSha}:package.json`], {
                  encoding: 'utf8',
                }),
              );
            } catch {
              previousVersion = null;
            }
          }

          const changed = previousVersion !== null &&
            currentVersion !== null &&
            previousVersion !== currentVersion;

          appendFileSync(outputPath, `changed=${changed}\n`);
          appendFileSync(outputPath, `previous=${previousVersion ?? ''}\n`);
          appendFileSync(outputPath, `current=${currentVersion ?? ''}\n`);

          console.log(`Previous simple-icons version: ${previousVersion || '(missing)'}`);
          console.log(`Current simple-icons version: ${currentVersion || '(missing)'}`);
          console.log(`Version changed: ${changed}`);
          EOF

      - uses: superfly/flyctl-actions/setup-flyctl@master
        if: ${{ github.event_name == 'workflow_dispatch' || steps.simple_icons.outputs.changed == 'true' }}

      - name: Deploy to Fly
        if: ${{ github.event_name == 'workflow_dispatch' || steps.simple_icons.outputs.changed == 'true' }}
        run: flyctl deploy --remote-only
        env:
          FLY_API_TOKEN: ${{ secrets.FLY_DEPLOY_TOKEN }}",
  "rationale": "The deploy job has representative successful history (recent runs complete in about 2 minutes) and no dependency-installation step, so dependency caching (P-LIT-GHA-CACHE) has nothing to cache, and cancellation-based patterns are contraindicated for deployment work (P-LIT-CANCEL-STALE lists release/deployment work as a contraindication). The P-LIT-CUSTOM-TIMEOUT pattern is supported by measured experiment evidence showing bounding a job with timeout-minutes reduced elapsed time (baseline 41s vs optimized 30s, ~26.8% savings) while preserving all steps and outcomes. Adding timeout-minutes: 5 to the deploy job bounds runaway consumption with ample headroom over normal ~2-minute runs, preserves every step and required check, and introduces no new network access, secrets, or privileged actions.",
  "evidence_ids": ["experiment:batch-interactive-three--fb8b16eb65a11508", "pattern:P-LIT-CUSTOM-TIMEOUT"]
}
